// ResolveCommit resolves rev to the full sha of a commit that exists in this
// repository, and whether there is one.
//
// Unlike RevParse, which echoes any 40-character sha back unchecked, a sha
// that is not in the object database is reported as not found.
func (g Client) ResolveCommit(ctx context.Context, rev string) (string, bool, error) {
	sha, err := g.run(ctx, "rev-parse", "--verify", "--quiet", "--end-of-options", rev+"^{commit}")
	if err != nil {
		// --quiet exits 1 with no output for a missing or non-commit rev.
		var exit *exec.ExitError
		if errors.As(err, &exit) && exit.ExitCode() == 1 {
			return "", false, nil
		}
		return "", false, fmt.Errorf("resolve %s: %w", rev, err)
	}
	return sha, sha != "", nil
}

